create table public.discussions (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, title text not null, body text not null, created_by uuid references public.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create index discussions_entity_idx on public.discussions(entity_type,entity_id) where deleted_at is null;
create table public.discussion_replies (id uuid primary key default gen_random_uuid(), discussion_id uuid not null references public.discussions(id) on delete cascade, parent_reply_id uuid references public.discussion_replies(id), body text not null, created_by uuid references public.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table public.likes (user_id uuid references public.users(id), entity_type text not null, entity_id uuid not null, created_at timestamptz not null default now(), primary key(user_id,entity_type,entity_id));
create table public.follows (follower_id uuid references public.users(id), entity_type text not null, entity_id uuid not null, created_at timestamptz not null default now(), primary key(follower_id,entity_type,entity_id));
create table public.collections (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id), name text not null, visibility text not null default 'private', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.collection_items (collection_id uuid references public.collections(id) on delete cascade, entity_type text not null, entity_id uuid not null, added_at timestamptz not null default now(), primary key(collection_id,entity_type,entity_id));
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users(id), type text not null, payload jsonb not null default '{}', read_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
